// Minimal batching sketch
typedef struct {
  uint64_t seq;
  struct io_req *reqs[32];
  int n;
} batch_t;

void batch_append(batch_t *b, struct io_req *r){
  if (b->n < 32) b->reqs[b->n++] = r;
}
```

